 ev('taylor_recognition_original','Multiculturalism and “The Politics of Recognition”',1992,[sid('taylor_mcgill'),sid('taylor_multi_credits')],'Taylor’s central essay with commentary by other writers; Amy Gutmann editor. The 1992 full text is not independently collated against 1994.'),
