adds=[];notes=[]
assert len(DATA)==2
for d in DATA:
 pid=d['pid'];assert pid not in N;assert (pid in P)==(pid=='peter_brown');assert A[pid]['confirmed_selected_person_lower_bound']==(102 if pid=='charles_taylor' else 101)
 identity=(P[pid].get('identity_note','')+' Addendum '+DAY+': ' if pid in P and P[pid].get('identity_note') else '')+d['identity']
 node=dict(id=pid,label=d['label'],layer=d['layer'],entry_kind='person',entry_type='Individual historian' if d['layer']=='historians' else 'Individual theorist',period=None,hunt_core_paradigm=False,date_label=' · '.join(e['label']+' ('+str(e['date']['year'])+')' for e in d['events']),description=d['description'],representative_figures_and_works=d['works'],source_ids=list(dict.fromkeys(d['old']+[s['id'] for s in d['sources']])),scope_note=d['scope'],chronology=dict(version=1,label='Selected contributions, publications and editions',selection_note='Selected work and contribution facts, not life dates, a continuous career span or a complete bibliography. Originals, editions, collective credits and interview dates remain distinct.',events=d['events'],intervals=[],continuation=dict(status='not_asserted',basis='Selected facts establish no continuous interval or last activity date.'),interpretation='Argument claims rely on precisely selected primary passages or individually attributed prior readings; bibliographic metadata supports dates/credits only.',prepared_on=DAY,editorial_record='data/production-batches/person-entries-'+REV+'/acceptance.json'))
 edges=[];ras=[]
 for i,r0 in enumerate(d['relations'],1):
  r=copy.deepcopy(r0);target=r['target'];assert target in N;inc=r.pop('incoming')
  r.update(proposal_id=PRE+pid+'_'+str(i),source=target if inc else pid,target=pid if inc else target,type='connection',directed=True,classification_basis='editorial_review')
  if N[target].get('entry_kind')!='person':
   if not inc:r['roster_row']=target
   if not any(x['person_id']==pid for x in N[target].get('representative_people',[])):
    ras.append(dict(node=target,proposal_id=r['proposal_id'],row=dict(person_id=pid,role='contributor',context=r['relationship'],works=d['works'],source_ids=r['source_ids'],basis='source_review')))
    if inc:r['roster_row']=dict(node=target,person_id=pid)
   adds.append(dict(node=target,field='source_ids',values=r['source_ids']))
  edges.append(r)
 draft=dict(status='proposal_for_review',prepared=DAY,applies_to='Baseline '+BASE+' to candidate '+REV,review_status='needs_independent_review',node=node,people_update=dict(id=pid,label=d['label'],node_id=pid,new=pid not in P,identity_note=identity),proposed_edges=edges,new_sources=d['sources'],source_addenda={},roster_additions=ras,edges_considered_not_proposed=['No citation-count-to-influence conversion or raw-author-key merge.','No existing collective arrows, source records, chronologies, roster contexts or strand prose changed.','No inference of Foucault influence from editorial introductions or reported conversational scenes.'])
 write(Path(pid)/'entry-draft.json',draft)
 ls=dict(person_id=pid,label=d['label'],status='living',death_year=None,death_precision=None,birth_year=d['birth'],checked_on=DAY,identity_rationale=identity,sources=d['life_sources'],confidence='high' if pid=='peter_brown' else 'medium',limits=d['life_limit'])
 write(Path(pid)/'life-status.json',ls)
 contexts=[dict(node=n['id'],rows=[copy.deepcopy(r) for r in n.get('representative_people',[]) if r['person_id']==pid],strands=[copy.deepcopy(s) for s in n.get('strands',[]) if pid in s.get('person_ids',[])]) for n in G['nodes'] if any(r['person_id']==pid for r in n.get('representative_people',[]))]
 pn=dict(person_id=pid,label=d['label'],eligibility=A[pid],count_proof=str(AUDIT.relative_to(ROOT)),count_scope='Clean positive named-work dissertation ID UNION is a lower bound, separate from the frozen first-author key total. No key merge or influence inference.',identity_scope=identity,existing_coverage=contexts,existing_sources_preserved=[copy.deepcopy(S[k]) for k in d['old']],new_source_scopes=d['sources'],reading_limit=d['scope'],life_status_record=pid+'/life-status.json',events=d['events'],relations=edges)
 write(Path(pid)/'research-notes.json',pn);notes.append(dict(person_id=pid,research=pid+'/research-notes.json',life=pid+'/life-status.json'))
write(Path('batch.json'),dict(revision=REV,baseline_revision=BASE,date=DAY,batch_dir='person-entries-'+REV,persons=[d['pid'] for d in DATA],extras=[],summary='Add the independently disambiguated Charles Taylor theory entry and Peter Brown historian entry, with bounded primary readings and dated contributions.',authorization='User authorizes completion of the remaining canon after identity resolution. Coordinator assigned these two clean qualifying lower-bound cases and retains canonical application; only this owned proposal is prepared.',rationale='Specific work concordances establish strict >100 eligibility without changing frozen author keys. Taylor remains a theoretical resource; Brown studies late-antique history. Original/edition/collection credits and primary reading extents remain explicit. Existing identities, source qualifications, collective arrows, roster and strand prose, coverage and chronology are preserved.',edge_revisions={},source_merges={},node_list_additions=adds))
write(Path('research-notes.json'),dict(prepared=DAY,baseline_revision=BASE,canonical_revision_observed=G['revision_history'][-1]['version'],canonical_sha256=hashlib.sha256((ROOT/'historiography-1920-2000.json').read_bytes()).hexdigest(),scope='Only owned packet writes; no apply, shared graph/code/docs/reading/life-master changes, no OpenAlex.',persons=notes,identity_audit='data/field-research/remaining-canon-2026-10-25/final-identity-pass/',preservation='Existing Stone source copied verbatim into Brown notes. No prior source note enlarged, existing endpoint repaired or field chronology replaced. New Taylor identity checked absent before creation.',transient_files=[dict(path=str(p.relative_to(HERE)),sha256=hashlib.sha256(p.read_bytes()).hexdigest(),bytes=p.stat().st_size,status='ignored_local_copy') for p in sorted((HERE/'research').iterdir()) if p.is_file() and p.name!='.gitignore']))
print('Prepared',REV,'2 people;',sum(len(d['events']) for d in DATA),'dated facts; 6 substantive relations. No apply.')
